INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(390893, 33587, 5767, '<td valign="top">Great image - the accent Number and the stairway just creat something that captured my attention.  excellent entry.</td>', 'Great image - the accent Number and the stairway just creat something that captured my attention.  excellent entry.', '2003-08-18 01:05:23.000000', NULL, 1),
(390898, 33822, 772, '<td valign="top">:fro :D</td>', ':fro :D', '2003-08-18 01:07:36.000000', NULL, 1),
(390899, 33844, 6600, '<td valign="top">Thought I might have a chance in this challenge....  until I saw this!  Great lighting, composition, and color tone.  Superb!</td>', 'Thought I might have a chance in this challenge....  until I saw this!  Great lighting, composition, and color tone.  Superb!', '2003-08-18 01:07:46.000000', NULL, 1),
(390902, 33311, 10594, '<td valign="top">The lighting is a bit harsh - lots of reflections on the leaves that I find a bit distracting. I also think the negative space would be more dramatic if the angle placed the butterfly more against the dark background.</td>', 'The lighting is a bit harsh - lots of reflections on the leaves that I find a bit distracting. I also think the negative space would be more dramatic if the angle placed the butterfly more against the dark background.', '2003-08-18 01:08:01.000000', NULL, 1),
(390903, 33583, 772, '<td valign="top">beautiful work... I love the way ''fog'' creates a clean canvas for a photographer :)</td>', 'beautiful work... I love the way ''fog'' creates a clean canvas for a photographer :)', '2003-08-18 01:08:14.000000', NULL, 1),
(390904, 33628, 772, '<td valign="top">this is an interesting macro, but I think your background takes away from the ''negative space'' concept here just a bit... the contrasts make my eye wander throught your ''negative space''...</td>', 'this is an interesting macro, but I think your background takes away from the ''negative space'' concept here just a bit... the contrasts make my eye wander throught your ''negative space''...', '2003-08-18 01:09:30.000000', NULL, 1),
(390905, 33100, 772, '<td valign="top">I don''t understand the ''negative space'' concept in this image...</td>', 'I don''t understand the ''negative space'' concept in this image...', '2003-08-18 01:10:03.000000', NULL, 1),
(390908, 34020, 772, '<td valign="top">very nicely executed shot... I traditionally would suggest some alternative compositions with the subject not ''dead'' centered...</td>', 'very nicely executed shot... I traditionally would suggest some alternative compositions with the subject not ''dead'' centered...', '2003-08-18 01:11:19.000000', NULL, 1),
(390909, 34010, 10594, '<td valign="top">Very nice. Definitely a great use of negative space. The blue of the sky is a little unappealing on my monitor - not quite sure why. Makes me want to see this in black and white and see if that would make it more dramatic.</td>', 'Very nice. Definitely a great use of negative space. The blue of the sky is a little unappealing on my monitor - not quite sure why. Makes me want to see this in black and white and see if that would make it more dramatic.', '2003-08-18 01:11:31.000000', NULL, 1),
(390910, 34016, 772, '<td valign="top">this is a beautiful shot, but I don''t see any negative space at all... the entire image is filled with color and contrasts...</td>', 'this is a beautiful shot, but I don''t see any negative space at all... the entire image is filled with color and contrasts...', '2003-08-18 01:12:07.000000', NULL, 1),
(390911, 33456, 10594, '<td valign="top">I really like this composition. The edges seem a bit soft, though.</td>', 'I really like this composition. The edges seem a bit soft, though.', '2003-08-18 01:13:22.000000', NULL, 1),
(390912, 33310, 6202, '<td valign="top">Very orginal...bear could use a little more saturation I do believe =o)</td>', 'Very orginal...bear could use a little more saturation I do believe =o)', '2003-08-18 01:14:13.000000', NULL, 1),
(390914, 34004, 10594, '<td valign="top">Awesome use of negative space. I think the lighting and colors are just perfect.</td>', 'Awesome use of negative space. I think the lighting and colors are just perfect.', '2003-08-18 01:14:16.000000', NULL, 1),
(390917, 33957, 772, '<td valign="top">negative space?  I don''t see any... :(</td>', 'negative space?  I don''t see any... :(', '2003-08-18 01:14:53.000000', NULL, 1),
(390918, 33100, 10594, '<td valign="top">Nice photo. I don''t feel the negative space is what does it for this one though.</td>', 'Nice photo. I don''t feel the negative space is what does it for this one though.', '2003-08-18 01:15:28.000000', NULL, 1),
(390919, 33854, 6870, '<td valign="top">I sure love that sky. Neg space works to add a sense of important-to-the-cosmos feel to thigns.</td>', 'I sure love that sky. Neg space works to add a sense of important-to-the-cosmos feel to thigns.', '2003-08-18 01:17:19.000000', NULL, 1),
(390920, 33733, 6870, '<td valign="top">I love the sillhouette here. The negative space isn''t as obvious or apparent, but this is such a well composed shot.</td>', 'I love the sillhouette here. The negative space isn''t as obvious or apparent, but this is such a well composed shot.', '2003-08-18 01:18:01.000000', NULL, 1),
(390921, 34015, 10263, '<td valign="top">Very nice. That wood is so beautiful, I love the earthy tones. Great negative space.</td>', 'Very nice. That wood is so beautiful, I love the earthy tones. Great negative space.', '2003-08-18 01:18:15.000000', NULL, 1),
(390923, 33893, 772, '<td valign="top">the ''glow'' around this limb makes it look a little strange.... it makes it look like the sky around the limb has been darkened....</td>', 'the ''glow'' around this limb makes it look a little strange.... it makes it look like the sky around the limb has been darkened....', '2003-08-18 01:18:36.000000', NULL, 1),
(390924, 33892, 7935, '<td valign="top">my eyes urt now  the red seems TOO boosted a 6</td>', 'my eyes urt now  the red seems TOO boosted a 6', '2003-08-18 01:18:39.000000', NULL, 1),
(390925, 33020, 10594, '<td valign="top">Nice composition, though the grain is pretty distracting. I think the negative space usage could be stronger as well.</td>', 'Nice composition, though the grain is pretty distracting. I think the negative space usage could be stronger as well.', '2003-08-18 01:18:50.000000', NULL, 1),
(390926, 33995, 6870, '<td valign="top">A simple shot, simply done, and simply of high quality. Nice work. The neg space seems to add a feeling that the light is watching over things below it.</td>', 'A simple shot, simply done, and simply of high quality. Nice work. The neg space seems to add a feeling that the light is watching over things below it.', '2003-08-18 01:18:56.000000', NULL, 1),
(390927, 33047, 6870, '<td valign="top">Unique and cool. The various colors play so well with the glass. Thanks for having that glass in such good focus.</td>', 'Unique and cool. The various colors play so well with the glass. Thanks for having that glass in such good focus.', '2003-08-18 01:19:47.000000', NULL, 1),
(390928, 33175, 10263, '<td valign="top">Yep, I think too much chaos. It seems way to busy to me and hard to look at for long.</td>', 'Yep, I think too much chaos. It seems way to busy to me and hard to look at for long.', '2003-08-18 01:20:15.000000', NULL, 1),
(390929, 33872, 6870, '<td valign="top">Neg space suggests the entire ship here. Very nice. Composition without the rule of thirds was a good choice, I feel, but I''m not sure why...</td>', 'Neg space suggests the entire ship here. Very nice. Composition without the rule of thirds was a good choice, I feel, but I''m not sure why...', '2003-08-18 01:20:38.000000', NULL, 1),
(390930, 34012, 7706, '<td valign="top">Contast is very cool. Sharpness is also very good. At first I thought the image was dark, however it really does add to the illusion. Its funny, as I type this now, I can only see the image in the corner of my eye and I see the vase not the model as when you are not  looking directly the dark areas look 100% black.</td>', 'Contast is very cool. Sharpness is also very good. At first I thought the image was dark, however it really does add to the illusion. Its funny, as I type this now, I can only see the image in the corner of my eye and I see the vase not the model as when you are not  looking directly the dark areas look 100% black.', '2003-08-18 01:20:40.000000', NULL, 1),
(390931, 33175, 772, '<td valign="top">i don''t understand the negative space concept of this photo...</td>', 'i don''t understand the negative space concept of this photo...', '2003-08-18 01:21:00.000000', NULL, 1),
(390932, 33554, 6870, '<td valign="top">Nice and inviting! Thanks, I do feel welcome! Try fiddling with more contrasts--darker darks, for instance to make the image pop.</td>', 'Nice and inviting! Thanks, I do feel welcome! Try fiddling with more contrasts--darker darks, for instance to make the image pop.', '2003-08-18 01:21:37.000000', NULL, 1),
(390933, 33649, 11034, '<td valign="top">Is a nice shoot, but I think that the main subjet is too big.</td>', 'Is a nice shoot, but I think that the main subjet is too big.', '2003-08-18 01:22:05.000000', NULL, 1),
(390934, 33452, 6870, '<td valign="top">Good use of out of focus here. The misshapen sun works for me, too, and an entire sky is suggested in which the sun can rise.</td>', 'Good use of out of focus here. The misshapen sun works for me, too, and an entire sky is suggested in which the sun can rise.', '2003-08-18 01:22:36.000000', NULL, 1),
(390935, 33835, 10594, '<td valign="top">I like this, but the colors seems a bit flat. More light might help create a greater contrast with the blue sky.</td>', 'I like this, but the colors seems a bit flat. More light might help create a greater contrast with the blue sky.', '2003-08-18 01:22:37.000000', NULL, 1),
(390936, 33583, 9073, '<td valign="top">Nice composition. Lovely, subtle colours. I really like this shot. 9</td>', 'Nice composition. Lovely, subtle colours. I really like this shot. 9', '2003-08-18 01:22:41.000000', NULL, 1),
(390937, 33020, 6870, '<td valign="top">Good eye for this sunset! A bit more contrast--darker darks, for instance, might help the image pop even more by providing darker tones to contrast the sun''s lighter ones?</td>', 'Good eye for this sunset! A bit more contrast--darker darks, for instance, might help the image pop even more by providing darker tones to contrast the sun''s lighter ones?', '2003-08-18 01:23:29.000000', NULL, 1),
(390938, 33753, 2923, '<td valign="top">Not enough DOF and the branch on the right is very annoying, otherwise this would be an image with high impact.</td>', 'Not enough DOF and the branch on the right is very annoying, otherwise this would be an image with high impact.', '2003-08-18 01:23:31.000000', NULL, 1),
(390940, 33366, 6870, '<td valign="top">Interesting textures. Not a lot of negative space, but it''s there! Gute Idee!</td>', 'Interesting textures. Not a lot of negative space, but it''s there! Gute Idee!', '2003-08-18 01:24:20.000000', NULL, 1),
(390942, 33047, 2567, '<td valign="top">Focus, colors, dof and composition is terrific.  But for a Negative Space challenge I''m seeing the background first and the bottle and vials last.  Good luck.</td>', 'Focus, colors, dof and composition is terrific.  But for a Negative Space challenge I''m seeing the background first and the bottle and vials last.  Good luck.', '2003-08-18 01:25:01.000000', NULL, 1),
(390943, 33315, 6870, '<td valign="top">Perfect popcorn placement procures punkish placebo. 9</td>', 'Perfect popcorn placement procures punkish placebo. 9', '2003-08-18 01:25:24.000000', NULL, 1),
(390944, 33628, 2923, '<td valign="top">Not sure if this counts has having negative space....</td>', 'Not sure if this counts has having negative space....', '2003-08-18 01:25:45.000000', NULL, 1),
(390945, 33448, 9073, '<td valign="top">Overexposure is evident on the cross. I know that to avoid that the clouds would be darker, but you could use tone curves to overcome that problem. I think that the cross should be completely solid for this to work really well. 6</td>', 'Overexposure is evident on the cross. I know that to avoid that the clouds would be darker, but you could use tone curves to overcome that problem. I think that the cross should be completely solid for this to work really well. 6', '2003-08-18 01:26:05.000000', NULL, 1),
(390948, 34001, 6870, '<td valign="top">Those are some of the most engaging clouds I''ve ever seen. I''m not sure about how the title fits in with the image, but I find the image very engaging with the diagonal lines and solid shapes contrasting those magnificent clouds. Negative space is very subtle here.</td>', 'Those are some of the most engaging clouds I''ve ever seen. I''m not sure about how the title fits in with the image, but I find the image very engaging with the diagonal lines and solid shapes contrasting those magnificent clouds. Negative space is very subtle here.', '2003-08-18 01:26:45.000000', NULL, 1),
(390949, 33893, 10643, '<td valign="top">The border and the glow are perhaps a little too much post-processing. A more natural shot showing the texture of the tree bark against the clouds would have more appeal for me.</td>', 'The border and the glow are perhaps a little too much post-processing. A more natural shot showing the texture of the tree bark against the clouds would have more appeal for me.', '2003-08-18 01:26:53.000000', NULL, 1),
(390950, 33431, 2923, '<td valign="top">Nice image but not sure if there is significant negative space to fit the challenge, still a nice image nevertheless.</td>', 'Nice image but not sure if there is significant negative space to fit the challenge, still a nice image nevertheless.', '2003-08-18 01:26:57.000000', NULL, 1),
(390952, 33373, 6870, '<td valign="top">I''mnot sure the image rotation is justified, but the tones of the rock are marvelous.</td>', 'I''mnot sure the image rotation is justified, but the tones of the rock are marvelous.', '2003-08-18 01:27:39.000000', NULL, 1),
(390953, 34009, 2567, '<td valign="top">Sorry but for this challenge I don''t think this works.  I see the background before I see the bird.  The background should accent the bird not hide it IMO.  Good luck.</td>', 'Sorry but for this challenge I don''t think this works.  I see the background before I see the bird.  The background should accent the bird not hide it IMO.  Good luck.', '2003-08-18 01:28:20.000000', NULL, 1),
(390955, 33310, 2923, '<td valign="top">cute.</td>', 'cute.', '2003-08-18 01:28:35.000000', NULL, 1),
(390956, 33311, 9073, '<td valign="top">The leaf is overblown, and the negative space doesn''t contribute much.</td>', 'The leaf is overblown, and the negative space doesn''t contribute much.', '2003-08-18 01:28:45.000000', NULL, 1),
(390957, 33948, 6870, '<td valign="top">Yellow and black contrast so nicely with each other. Neg space seems to add a sense that there is more to the world of the photo.</td>', 'Yellow and black contrast so nicely with each other. Neg space seems to add a sense that there is more to the world of the photo.', '2003-08-18 01:28:53.000000', NULL, 1),
(390958, 33923, 10643, '<td valign="top">I like the fog/rain. You can almost feel the frustration of not being able to fly. I do wish there was a *little* more contrast; it doesn''t look completely intentional the way it is.</td>', 'I like the fog/rain. You can almost feel the frustration of not being able to fly. I do wish there was a *little* more contrast; it doesn''t look completely intentional the way it is.', '2003-08-18 01:29:01.000000', NULL, 1),
(390959, 33370, 2923, '<td valign="top">i think it''d be better image without the light. 7</td>', 'i think it''d be better image without the light. 7', '2003-08-18 01:29:03.000000', NULL, 1),
(390964, 34029, 2923, '<td valign="top">image is a bit noisy - rainier is a beautiful place, but i am not sure if the blank sky works for it well.</td>', 'image is a bit noisy - rainier is a beautiful place, but i am not sure if the blank sky works for it well.', '2003-08-18 01:30:24.000000', NULL, 1),
(390965, 33651, 6870, '<td valign="top">Such marvelous tones here! I''d like to see what would happen if the boat were farther to the right--more rule of thirds orientation. It might make the negative space speak even more loudly of the encompassing world the boat is in.</td>', 'Such marvelous tones here! I''d like to see what would happen if the boat were farther to the right--more rule of thirds orientation. It might make the negative space speak even more loudly of the encompassing world the boat is in.', '2003-08-18 01:30:24.000000', NULL, 1),
(390966, 33250, 3554, '<td valign="top">I like the reflection, but I''m not too crazy about the yellow streak on the left side.</td>', 'I like the reflection, but I''m not too crazy about the yellow streak on the left side.', '2003-08-18 01:30:55.000000', NULL, 1),
(390967, 33903, 6870, '<td valign="top">The neg space here is so interesting, one can hardly call it negative, but I do and I find this photo really engaging and fun to explore.</td>', 'The neg space here is so interesting, one can hardly call it negative, but I do and I find this photo really engaging and fun to explore.', '2003-08-18 01:31:20.000000', NULL, 1),
(390969, 33889, 10643, '<td valign="top">Nice job. The stark white sky forms an interesting shape, and the leading lines of the rooftops have that nice streetlight to reveal at the end.</td>', 'Nice job. The stark white sky forms an interesting shape, and the leading lines of the rooftops have that nice streetlight to reveal at the end.', '2003-08-18 01:31:35.000000', NULL, 1),
(390970, 34029, 2567, '<td valign="top">Nice shot.  I like the composition.  Meets the challenge.   Only thing is there are some white spots on the right and near the bottom that I find distracting but I\''m nit picking.  I really find this shot effective.  Good luck.</td>', 'Nice shot.  I like the composition.  Meets the challenge.   Only thing is there are some white spots on the right and near the bottom that I find distracting but I\''m nit picking.  I really find this shot effective.  Good luck.', '2003-08-18 01:31:42.000000', NULL, 1),
(390971, 34016, 9073, '<td valign="top">Nice colours. Good use of positive space for a full-frame shot.</td>', 'Nice colours. Good use of positive space for a full-frame shot.', '2003-08-18 01:32:01.000000', NULL, 1),
(390972, 33544, 6870, '<td valign="top">These fighting kites are so fun. I''ve only done kite fighting a few times, but what a great time. The photo is nice, too. I''d like to see more contrast perhaps to see that kite pop from the gray of the clouds--darker darks, lighter lights perhaps? neg. space is used very well here to orient the kite in its environment.</td>', 'These fighting kites are so fun. I''ve only done kite fighting a few times, but what a great time. The photo is nice, too. I''d like to see more contrast perhaps to see that kite pop from the gray of the clouds--darker darks, lighter lights perhaps? neg. space is used very well here to orient the kite in its environment.', '2003-08-18 01:32:59.000000', NULL, 1),
(390973, 33465, 3554, '<td valign="top">I don''t see how this meets the challenge. I don''t feel the space around the boy is the strength of your shot.</td>', 'I don''t see how this meets the challenge. I don''t feel the space around the boy is the strength of your shot.', '2003-08-18 01:33:03.000000', NULL, 1),
(390974, 34019, 10643, '<td valign="top">Great colors here! The yellow-green tinge of the sky before a storm is dead on.</td>', 'Great colors here! The yellow-green tinge of the sky before a storm is dead on.', '2003-08-18 01:33:06.000000', NULL, 1),
(390975, 33891, 4388, '<td valign="top">the challenge says use the surrounding space of your subject to create the wow of the photograph. the surrounding space is black in this image.</td>', 'the challenge says use the surrounding space of your subject to create the wow of the photograph. the surrounding space is black in this image.', '2003-08-18 01:33:13.000000', NULL, 1),
(390977, 33373, 9073, '<td valign="top">This makes me dizzy. Good effect.</td>', 'This makes me dizzy. Good effect.', '2003-08-18 01:33:33.000000', NULL, 1),
(390978, 33448, 3554, '<td valign="top">Nice.  :)  Definitely creates the Wow!</td>', 'Nice.  :)  Definitely creates the Wow!', '2003-08-18 01:33:34.000000', NULL, 1),
(390979, 33450, 4388, '<td valign="top">the challenge says to use the surrounding space of your subject to create the wow of the photograph. I don''t see that in this image.</td>', 'the challenge says to use the surrounding space of your subject to create the wow of the photograph. I don''t see that in this image.', '2003-08-18 01:34:21.000000', NULL, 1),
(390980, 34009, 6870, '<td valign="top">My kids love the sound these make. We have mourning doves right outside our window. I like how you neg space is not really all that negative. Certainly the bird gets the focus here, but the leaves are interesting, too. Maybe that precludes them from belonging to a negative space? I like.</td>', 'My kids love the sound these make. We have mourning doves right outside our window. I like how you neg space is not really all that negative. Certainly the bird gets the focus here, but the leaves are interesting, too. Maybe that precludes them from belonging to a negative space? I like.', '2003-08-18 01:34:34.000000', NULL, 1),
(390981, 33013, 11034, '<td valign="top">A very nice pic. One of my favorites.</td>', 'A very nice pic. One of my favorites.', '2003-08-18 01:35:00.000000', NULL, 1),
(390982, 33629, 10643, '<td valign="top">My favorite bug picture in this challenge so far! It''s quite a feat to give so much personality to someone so small. Nice job. :)</td>', 'My favorite bug picture in this challenge so far! It''s quite a feat to give so much personality to someone so small. Nice job. :)', '2003-08-18 01:35:09.000000', NULL, 1),
(390983, 34023, 4388, '<td valign="top">the white is blown out and the tunnel is not very interesting.</td>', 'the white is blown out and the tunnel is not very interesting.', '2003-08-18 01:35:20.000000', NULL, 1),
(390984, 33310, 6870, '<td valign="top">I''ll give you extra points for creativity and for the joke here. Bravely done, sir or madam! Bravely done!</td>', 'I''ll give you extra points for creativity and for the joke here. Bravely done, sir or madam! Bravely done!', '2003-08-18 01:35:26.000000', NULL, 1),
(390985, 33304, 6600, '<td valign="top">Very nicely done!  Love the contrast created by the great lighting.  Excellent.</td>', 'Very nicely done!  Love the contrast created by the great lighting.  Excellent.', '2003-08-18 01:35:35.000000', NULL, 1),
(390986, 33820, 4388, '<td valign="top">can''t tell what it is, and the space surrounding the subject does not create the wow.</td>', 'can''t tell what it is, and the space surrounding the subject does not create the wow.', '2003-08-18 01:36:02.000000', NULL, 1),
(390987, 34017, 10594, '<td valign="top">Nice close up photo, but I don''t believe the negative space is a strength of this picture.</td>', 'Nice close up photo, but I don''t believe the negative space is a strength of this picture.', '2003-08-18 01:36:11.000000', NULL, 1),
(390988, 34031, 6870, '<td valign="top">Amazing water color--there''s a good eye! Ducks are nicely placed so the attn is on the water.  I wish the ducks were as clear and sharp as the water, though.</td>', 'Amazing water color--there''s a good eye! Ducks are nicely placed so the attn is on the water.  I wish the ducks were as clear and sharp as the water, though.', '2003-08-18 01:36:23.000000', NULL, 1),
(390989, 33832, 10732, '<td valign="top">the lighting was really great here</td>', 'the lighting was really great here', '2003-08-18 01:36:31.000000', NULL, 1),
(390990, 33568, 4388, '<td valign="top">nice shot but the surrounding space does not create the wow.</td>', 'nice shot but the surrounding space does not create the wow.', '2003-08-18 01:36:34.000000', NULL, 1),
(390993, 33872, 5705, '<td valign="top">The white is so WHITE and the red so RED-- perfect composition, and wonderfull image--  frame it!!</td>', 'The white is so WHITE and the red so RED-- perfect composition, and wonderfull image--  frame it!!', '2003-08-18 01:37:53.000000', NULL, 1),
(390994, 33149, 4388, '<td valign="top">i like abstracts like this, i wish there was a little something more to give me a bearing on what i am looking at.</td>', 'i like abstracts like this, i wish there was a little something more to give me a bearing on what i am looking at.', '2003-08-18 01:37:57.000000', NULL, 1),
(390995, 33822, 9073, '<td valign="top">humourous.</td>', 'humourous.', '2003-08-18 01:38:12.000000', NULL, 1),
(390996, 33234, 6870, '<td valign="top">Placing the bonzai center makes IT the focus and suggests that IT is what we should be looking at almost exclusively. Using the rule of thirds would  invite us to also look at its environment and would suggest that it belongs in this mysterious, foggy world. Your choice, of course, but I would experiment with moving it to one side or the other. 7</td>', 'Placing the bonzai center makes IT the focus and suggests that IT is what we should be looking at almost exclusively. Using the rule of thirds would  invite us to also look at its environment and would suggest that it belongs in this mysterious, foggy world. Your choice, of course, but I would experiment with moving it to one side or the other. 7', '2003-08-18 01:38:31.000000', NULL, 1),
(390997, 33957, 2567, '<td valign="top">I''m having trouble thinking this meets the challenge IMO.  I really don''t see any negative space in this shot.</td>', 'I''m having trouble thinking this meets the challenge IMO.  I really don''t see any negative space in this shot.', '2003-08-18 01:38:35.000000', NULL, 1),
(390998, 33548, 4388, '<td valign="top">i like the colors, wish the ducks were more visible.</td>', 'i like the colors, wish the ducks were more visible.', '2003-08-18 01:38:38.000000', NULL, 1),
