INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(391487, 33952, 7857, '<td valign="top">I like the texture coming from the water, it''s more fine than just a wavey appearance and it seems to work well with the slight colour change up to the top right corner. Nice choice, slightly blown out on the side of the boat but there''s not always anything that can be done about that. Good luck with it.</td>', 'I like the texture coming from the water, it''s more fine than just a wavey appearance and it seems to work well with the slight colour change up to the top right corner. Nice choice, slightly blown out on the side of the boat but there''s not always anything that can be done about that. Good luck with it.', '2003-08-18 11:39:12.000000', NULL, 1),
(391488, 34009, 8779, '<td valign="top">Gorgeous bird. However, I dont feel that the leaves and branches are uniform enough to give a "background feel". Perhaps a closer crop on the bird to try to get rid of most of the branches? Or perhaps a wider aperture? =)</td>', 'Gorgeous bird. However, I dont feel that the leaves and branches are uniform enough to give a "background feel". Perhaps a closer crop on the bird to try to get rid of most of the branches? Or perhaps a wider aperture? =)', '2003-08-18 11:39:15.000000', NULL, 1),
(391489, 33218, 7504, '<td valign="top">Very nicely done!  The bubbles really add to the urgency of the shot.  10</td>', 'Very nicely done!  The bubbles really add to the urgency of the shot.  10', '2003-08-18 11:40:05.000000', NULL, 1),
(391490, 33826, 7504, '<td valign="top">The tilt of the shot adds to the movement of the surfboarder.  Nice.</td>', 'The tilt of the shot adds to the movement of the surfboarder.  Nice.', '2003-08-18 11:40:46.000000', NULL, 1),
(391494, 33587, 7504, '<td valign="top">I like this a lot.  Very clean, interesting shadows.  Well done.</td>', 'I like this a lot.  Very clean, interesting shadows.  Well done.', '2003-08-18 11:46:34.000000', NULL, 1),
(391497, 33013, 7504, '<td valign="top">I love the simplicity of this shot.  Clean and b/w is a great choice.  10</td>', 'I love the simplicity of this shot.  Clean and b/w is a great choice.  10', '2003-08-18 11:47:26.000000', NULL, 1),
(391506, 33747, 10799, '<td valign="top">This is wonderful!  The blue sky against the white lines makes it something special.<br/></td>', 'This is wonderful!  The blue sky against the white lines makes it something special.', '2003-08-18 11:52:09.000000', NULL, 1),
(391507, 34000, 7543, '<td valign="top">Nice moment! Great crop</td>', 'Nice moment! Great crop', '2003-08-18 11:52:25.000000', NULL, 1),
(391509, 33893, 8779, '<td valign="top">I see you had a very interesting idea. However, a few elements <i>may</i> improve the image...<br/> <br/>Firstly, the bright white ring around the branch doesnt work for me. Try using 0 or a very small number of pixels when deleting background as you can immediately see that it was layered on. also, silhoettes do not work well with outlines.<br/> <br/>Secondly, perhaps you could have get a few more branches? As at the moment, I do not think that the subject is interesting enough.<br/> <br/>Lastly, I know you cannot control weather, perhaps selecting a sky area with a <i>little</i> more blueness. I know that a negative space is meant to be quite uniform, but this section of sky does not give the image the WOW factor.<br/> <br/>Just some suggestions. =)</td>', 'I see you had a very interesting idea. However, a few elements may improve the image... Firstly, the bright white ring around the branch doesnt work for me. Try using 0 or a very small number of pixels when deleting background as you can immediately see that it was layered on. also, silhoettes do not work well with outlines. Secondly, perhaps you could have get a few more branches? As at the moment, I do not think that the subject is interesting enough. Lastly, I know you cannot control weather, perhaps selecting a sky area with a little more blueness. I know that a negative space is meant to be quite uniform, but this section of sky does not give the image the WOW factor. Just some suggestions. =)', '2003-08-18 11:55:33.000000', NULL, 1),
(391510, 33955, 7543, '<td valign="top">Flott, var reyndar svipað konsept í einhverju dagblaðanna um daginn. Flott crop og mjög góð lýsing.</td>', 'Flott, var reyndar svipað konsept í einhverju dagblaðanna um daginn. Flott crop og mjög góð lýsing.', '2003-08-18 11:57:03.000000', NULL, 1),
(391511, 34028, 92, '<td valign="top">oh I love this. The b/w works wonderful ! The composition just draws the eye in. GREAT photo !</td>', 'oh I love this. The b/w works wonderful ! The composition just draws the eye in. GREAT photo !', '2003-08-18 11:57:48.000000', NULL, 1),
(391513, 33737, 7543, '<td valign="top">Great composition, and the title is just great.</td>', 'Great composition, and the title is just great.', '2003-08-18 11:58:24.000000', NULL, 1),
(391515, 34006, 8779, '<td valign="top">Just one niggle, the image looks a little too compressed. A good quality image, I feel, really makes a big difference. =)<br/> <br/>PS&gt; Have I seen these marble-y things before?</td>', 'Just one niggle, the image looks a little too compressed. A good quality image, I feel, really makes a big difference. =) PS> Have I seen these marble-y things before?', '2003-08-18 12:00:02.000000', NULL, 1),
(391516, 34029, 7543, '<td valign="top">I think NeatImage would do good for this nice shot</td>', 'I think NeatImage would do good for this nice shot', '2003-08-18 12:00:25.000000', NULL, 1),
(391518, 33417, 92, '<td valign="top">Awesome photo !</td>', 'Awesome photo !', '2003-08-18 12:02:45.000000', NULL, 1),
(391519, 33822, 6870, '<td valign="top">Oops! It looks like we both had similar ideas. LOL. Yours is executed very well. I love the expression on the guy''s face!</td>', 'Oops! It looks like we both had similar ideas. LOL. Yours is executed very well. I love the expression on the guy''s face!', '2003-08-18 12:04:08.000000', NULL, 1),
(391522, 34017, 8779, '<td valign="top">You have really captured the animals characters here. I''m scared just looking at this photo. <br/> <br/>To me, the subject is the eye. The rest of the image is my space. I know that the teeth are very important, but before the image finished loading the image, just from looking at the piercing eye, it created a ''flee-really-far-because-I-am-really-scared'' effect. <br/> <br/>So, perhaps, with a close crop of this image without the teeth and the ''other background'', would make the onlooker concentrate more on the eye than be distracted by everything else and go WOW.<br/> <br/>Also, I see that the other eye is a very little blurry, so perhaps a narrower aperture?<br/> <br/>PS&gt; If I got the definition of Negative space wrong, pls PM me with the right on. =)</td>', 'You have really captured the animals characters here. I''m scared just looking at this photo.  To me, the subject is the eye. The rest of the image is my space. I know that the teeth are very important, but before the image finished loading the image, just from looking at the piercing eye, it created a ''flee-really-far-because-I-am-really-scared'' effect.  So, perhaps, with a close crop of this image without the teeth and the ''other background'', would make the onlooker concentrate more on the eye than be distracted by everything else and go WOW. Also, I see that the other eye is a very little blurry, so perhaps a narrower aperture? PS> If I got the definition of Negative space wrong, pls PM me with the right on. =)', '2003-08-18 12:07:23.000000', NULL, 1),
(391525, 34025, 6624, '<td valign="top">nice quote</td>', 'nice quote', '2003-08-18 12:08:46.000000', NULL, 1),
(391528, 33926, 6624, '<td valign="top">person reaction:  there is a foreshortening of the fingers that is slightly "off" for me ... instead of reaching for space could they have curled a bit and been holding it?</td>', 'person reaction:  there is a foreshortening of the fingers that is slightly "off" for me ... instead of reaching for space could they have curled a bit and been holding it?', '2003-08-18 12:10:04.000000', NULL, 1),
(391531, 33814, 8779, '<td valign="top">That is a brilliant silhoette of the little child. But personally, I would have much preferred a close crop of the boy cutting out the rest of the landscape and the wooden deck, because I think that they are a little distracting, and the reflections immediately tell you it is a sunset/rise without the actual sun. <br/> <br/>Also, the deck looks a little wonky with the straight horizon, so it''s a little offputting.<br/> <br/>=)</td>', 'That is a brilliant silhoette of the little child. But personally, I would have much preferred a close crop of the boy cutting out the rest of the landscape and the wooden deck, because I think that they are a little distracting, and the reflections immediately tell you it is a sunset/rise without the actual sun.  Also, the deck looks a little wonky with the straight horizon, so it''s a little offputting. =)', '2003-08-18 12:10:49.000000', NULL, 1),
(391532, 33047, 6624, '<td valign="top">I am not sure this space is negative, it is very active to me, but a nice image</td>', 'I am not sure this space is negative, it is very active to me, but a nice image', '2003-08-18 12:11:10.000000', NULL, 1),
(391534, 33889, 8779, '<td valign="top">If we are working on this image that we already have, I would personally have just chopped off the lamp and the third building as it breaks the uniformity of the white sky. <br/> <br/>However, as you took the picture, you could have included <i>more</i> of the third building, but at the moment, it is in between and a little ''incomfortable''.<br/> <br/>These are just suggestions =)</td>', 'If we are working on this image that we already have, I would personally have just chopped off the lamp and the third building as it breaks the uniformity of the white sky.  However, as you took the picture, you could have included more of the third building, but at the moment, it is in between and a little ''incomfortable''. These are just suggestions =)', '2003-08-18 12:15:07.000000', NULL, 1),
(391536, 33047, 92, '<td valign="top">One of my favs this week. This deserves a ribbon ! Best of luck ! 10</td>', 'One of my favs this week. This deserves a ribbon ! Best of luck ! 10', '2003-08-18 12:15:34.000000', NULL, 1),
(391537, 33304, 92, '<td valign="top">one word ... AWESOME ! 10</td>', 'one word ... AWESOME ! 10', '2003-08-18 12:16:28.000000', NULL, 1),
(391539, 33756, 8779, '<td valign="top">I love this toad. All it''s bumps and colors are brilliant!<br/> <br/>However, at the moment, it seems a little.. ''short?'' like it''s been cropped too tightly. But, you could go even further by cropping off the whole of his arm, to stop just beyond the brown ''wooden-like'' object on its head and cropping up to his chin. I suggest to crop up to the chin because it looks like it''s a little top heavy.<br/> <br/>Try it. Just scroll up enough to chop off it''s hands and place a piece of paper over the body.<br/> <br/>This is just a suggestion =)</td>', 'I love this toad. All it''s bumps and colors are brilliant! However, at the moment, it seems a little.. ''short?'' like it''s been cropped too tightly. But, you could go even further by cropping off the whole of his arm, to stop just beyond the brown ''wooden-like'' object on its head and cropping up to his chin. I suggest to crop up to the chin because it looks like it''s a little top heavy. Try it. Just scroll up enough to chop off it''s hands and place a piece of paper over the body. This is just a suggestion =)', '2003-08-18 12:19:51.000000', NULL, 1),
(391542, 34000, 6870, '<td valign="top">Now THAT''s negative space in the right place for impact! Pun intended. 9</td>', 'Now THAT''s negative space in the right place for impact! Pun intended. 9', '2003-08-18 12:20:25.000000', NULL, 1),
(391543, 33013, 6870, '<td valign="top">Gorgeous tones. THe white and sharpness of the flower creates the  negative space behind. 10</td>', 'Gorgeous tones. THe white and sharpness of the flower creates the  negative space behind. 10', '2003-08-18 12:20:59.000000', NULL, 1),
