(392563, 34014, 6199, '<td valign="top">I don''t like that powe cord up against the wall. Otherwise good!</td>', 'I don''t like that powe cord up against the wall. Otherwise good!', '2003-08-19 06:53:07.000000', NULL, 1),
(392564, 33865, 6059, '<td valign="top">hehe, the tractor is faraway...<br/>good idea, and very well captured... it is really nice work<br/> <br/>you should maybe get yourself a circular polirizer filter, to get the sky more deep blue...</td>', 'hehe, the tractor is faraway...good idea, and very well captured... it is really nice work you should maybe get yourself a circular polirizer filter, to get the sky more deep blue...', '2003-08-19 06:54:45.000000', NULL, 1),
(392565, 34019, 6059, '<td valign="top">wow, great sky there, good lowkey lightning on the table...<br/>good capture... congrats.<br/> <br/> <br/>v.</td>', 'wow, great sky there, good lowkey lightning on the table...good capture... congrats.  v.', '2003-08-19 06:56:08.000000', NULL, 1),
(392567, 33583, 6059, '<td valign="top">Great fog there, great colors, I love those berries also...<br/>the angle is cool and I don''t think I can tell you how to improve anything ;)</td>', 'Great fog there, great colors, I love those berries also...the angle is cool and I don''t think I can tell you how to improve anything ;)', '2003-08-19 06:57:36.000000', NULL, 1),
