(398154, 34004, 6771, '<td valign="top">Very nice colors and focus.</td>', 'Very nice colors and focus.', '2003-08-24 23:37:01.000000', NULL, 1),
(398156, 34001, 6771, '<td valign="top">Excellent view.  Colors are awesome.  love the silhouette</td>', 'Excellent view.  Colors are awesome.  love the silhouette', '2003-08-24 23:38:20.000000', NULL, 1),
(398157, 33013, 6771, '<td valign="top">great use of B&amp;W.  love the DOF and brightness of the flower.  draws the eye right to it</td>', 'great use of B&W.  love the DOF and brightness of the flower.  draws the eye right to it', '2003-08-24 23:40:36.000000', NULL, 1),
(398158, 33049, 6771, '<td valign="top">Like this much better with more depth of field and sharper focus</td>', 'Like this much better with more depth of field and sharper focus', '2003-08-24 23:41:42.000000', NULL, 1),
(398160, 33822, 6771, '<td valign="top">Love the idea and inference of an afro</td>', 'Love the idea and inference of an afro', '2003-08-24 23:43:37.000000', NULL, 1),
(398161, 33629, 9073, '<td valign="top">Cute, little buddy.</td>', 'Cute, little buddy.', '2003-08-24 23:44:22.000000', NULL, 1),
