INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(398164, 33955, 6771, '<td valign="top">Great perspective!  that a real pool?</td>', 'Great perspective!  that a real pool?', '2003-08-24 23:45:55.000000', NULL, 1),
(398167, 33373, 6771, '<td valign="top">Very interesting perspective</td>', 'Very interesting perspective', '2003-08-24 23:46:43.000000', NULL, 1),
(398168, 33835, 9073, '<td valign="top">I wish that the yellows were just a touch brighter. As is, I like this. 6</td>', 'I wish that the yellows were just a touch brighter. As is, I like this. 6', '2003-08-24 23:47:22.000000', NULL, 1),
(398173, 33747, 9073, '<td valign="top">nice lines, vivid colours.</td>', 'nice lines, vivid colours.', '2003-08-24 23:51:52.000000', NULL, 1),
(398183, 33369, 9073, '<td valign="top">Sorry, not enough texture showing for this shot to work for me.</td>', 'Sorry, not enough texture showing for this shot to work for me.', '2003-08-25 00:16:02.000000', NULL, 1),
(398186, 33955, 527, '<td valign="top">I really enjoy this photo but I don''t see it fitting the challenge that well because there are interesting things to look at throughout the background. So I don''t see it as an effective use of negative space in order to support the main subject. It seams like it would fit a "perspective" challenge or some other one. It is vey good though with good clarity and bright colors.  -T</td>', 'I really enjoy this photo but I don''t see it fitting the challenge that well because there are interesting things to look at throughout the background. So I don''t see it as an effective use of negative space in order to support the main subject. It seams like it would fit a "perspective" challenge or some other one. It is vey good though with good clarity and bright colors.  -T', '2003-08-25 00:20:42.000000', NULL, 1),
(398191, 33368, 8377, '<td valign="top">Beautiful, I love all the sky.</td>', 'Beautiful, I love all the sky.', '2003-08-25 00:22:59.000000', NULL, 1),
(398194, 33842, 8377, '<td valign="top">I love this pic.  I love all the green grass, and then you see the goat.  How did you get the goat to just stare at the camera?  It looks like he is saying "hi there." :)</td>', 'I love this pic.  I love all the green grass, and then you see the goat.  How did you get the goat to just stare at the camera?  It looks like he is saying "hi there." :)', '2003-08-25 00:24:20.000000', NULL, 1),
(398195, 33651, 527, '<td valign="top">Nice and simple with good clarity and bold colors. I may have shown some sand direct under the boat but I''m not sure, I would have to see it.  -T</td>', 'Nice and simple with good clarity and bold colors. I may have shown some sand direct under the boat but I''m not sure, I would have to see it.  -T', '2003-08-25 00:24:30.000000', NULL, 1),
(398200, 34029, 8377, '<td valign="top">Beautiful shot!  The mountain seems to be floating, and all the sky at the top makes the shot unique and beautiful.</td>', 'Beautiful shot!  The mountain seems to be floating, and all the sky at the top makes the shot unique and beautiful.', '2003-08-25 00:25:36.000000', NULL, 1),
(398202, 33995, 8377, '<td valign="top">I love the composition of this one!  Did you change the colors of the sky at all, or were they really those colors?  If they were those colors, what a pretty place to be!</td>', 'I love the composition of this one!  Did you change the colors of the sky at all, or were they really those colors?  If they were those colors, what a pretty place to be!', '2003-08-25 00:26:57.000000', NULL, 1),
(398206, 33251, 527, '<td valign="top">I''m not sure what it is but it doesn''t matter, I like it. Nice composition and choice of B &amp; W.  -T</td>', 'I''m not sure what it is but it doesn''t matter, I like it. Nice composition and choice of B & W.  -T', '2003-08-25 00:28:57.000000', NULL, 1),
(398207, 33467, 8377, '<td valign="top">I would have liked to see just a bit more of the pole in this shot, but the light is so pretty and the sky too.  Good clarity.</td>', 'I would have liked to see just a bit more of the pole in this shot, but the light is so pretty and the sky too.  Good clarity.', '2003-08-25 00:29:07.000000', NULL, 1),
(398209, 34000, 8377, '<td valign="top">I love this shot!  Brave fellow there.  How high up was he?  I see all of the sky below, and I just think.. wow.  The colors in this photo are really great, the red is the perfect shade of red.  I also really like your border.</td>', 'I love this shot!  Brave fellow there.  How high up was he?  I see all of the sky below, and I just think.. wow.  The colors in this photo are really great, the red is the perfect shade of red.  I also really like your border.', '2003-08-25 00:31:16.000000', NULL, 1),
(398213, 34026, 527, '<td valign="top">Wow, this is great. This really defines negative space. Excellent perspective, composition, textures and colors. I love the blue tones that help accentuate the skin colors. Well done.  -T</td>', 'Wow, this is great. This really defines negative space. Excellent perspective, composition, textures and colors. I love the blue tones that help accentuate the skin colors. Well done.  -T', '2003-08-25 00:33:36.000000', NULL, 1),
(398215, 33872, 8377, '<td valign="top">I love this shot.  Excellent clarity, Makes me feel like I''m right there.  I like your choice of subject also.</td>', 'I love this shot.  Excellent clarity, Makes me feel like I''m right there.  I like your choice of subject also.', '2003-08-25 00:34:11.000000', NULL, 1),
(398222, 33948, 10275, '<td valign="top">Very good use of flash. Great sharpness and detail. The border actually works on this image and it''s good that it is not bright or distracting. Very well done! 9</td>', 'Very good use of flash. Great sharpness and detail. The border actually works on this image and it''s good that it is not bright or distracting. Very well done! 9', '2003-08-25 00:40:38.000000', NULL, 1),
(398224, 33933, 10275, '<td valign="top">Shell could have been on an angle to ad interest. Love the texture in this picture. The colours are very nice on the shell.  Good use of neg. space.</td>', 'Shell could have been on an angle to ad interest. Love the texture in this picture. The colours are very nice on the shell.  Good use of neg. space.', '2003-08-25 00:42:45.000000', NULL, 1),
(398225, 34029, 10275, '<td valign="top">Little bit fuzzy, but I know it''s hard with this kind of image to achieve sharpness. Also, I know this is negative space challenge, but sometimes less is actually more.</td>', 'Little bit fuzzy, but I know it''s hard with this kind of image to achieve sharpness. Also, I know this is negative space challenge, but sometimes less is actually more.', '2003-08-25 00:44:32.000000', NULL, 1),
(398226, 33629, 10275, '<td valign="top">Great and funny shot. He is laughing at me :-)) Good negative space around him. Nice macro. Looks something like from the movie "bug''s life".</td>', 'Great and funny shot. He is laughing at me :-)) Good negative space around him. Nice macro. Looks something like from the movie "bug''s life".', '2003-08-25 00:46:01.000000', NULL, 1),
(398228, 33995, 10275, '<td valign="top">Very nice silluette and colour. The shrubs actually add additional interest to the image, otherwise just with the lantern it would have been somewhat simple.</td>', 'Very nice silluette and colour. The shrubs actually add additional interest to the image, otherwise just with the lantern it would have been somewhat simple.', '2003-08-25 00:47:22.000000', NULL, 1),
(398229, 33544, 10275, '<td valign="top">Very nice photo. My suggestion would be boost the blue of the sky a little through hue &amp; saturation to contrast with other colours.</td>', 'Very nice photo. My suggestion would be boost the blue of the sky a little through hue & saturation to contrast with other colours.', '2003-08-25 00:47:50.000000', NULL, 1),
(398230, 33760, 10275, '<td valign="top">Very nice point of veiw. I like the shadow - it ads additional interest to the image. Well cropped as well.</td>', 'Very nice point of veiw. I like the shadow - it ads additional interest to the image. Well cropped as well.', '2003-08-25 00:48:13.000000', NULL, 1),
(398231, 33892, 10275, '<td valign="top">Amazing photo. One of the WOW images in this category. Lovely red and black contrast. Very well done.</td>', 'Amazing photo. One of the WOW images in this category. Lovely red and black contrast. Very well done.', '2003-08-25 00:49:20.000000', NULL, 1),
(398234, 33304, 9241, '<td valign="top">Very nice shot, great lighting and detail, focus is dead on....only problem as I see it is the WOW is the subject, not the negative space. 4</td>', 'Very nice shot, great lighting and detail, focus is dead on....only problem as I see it is the WOW is the subject, not the negative space. 4', '2003-08-25 00:50:28.000000', NULL, 1),
(398235, 34004, 10275, '<td valign="top">I love the soft feeling of this photo. Great colour and setup.</td>', 'I love the soft feeling of this photo. Great colour and setup.', '2003-08-25 00:50:32.000000', NULL, 1),
(398236, 33319, 9241, '<td valign="top">mirror</td>', 'mirror', '2003-08-25 00:51:24.000000', NULL, 1),
(398239, 33431, 10275, '<td valign="top">Very beautiful setup. Was the green cast intentional? Green is usually not associated well with body shots. It almost look as if it were shot through a thin green silk screen. Lovely composition.</td>', 'Very beautiful setup. Was the green cast intentional? Green is usually not associated well with body shots. It almost look as if it were shot through a thin green silk screen. Lovely composition.', '2003-08-25 00:53:10.000000', NULL, 1),
(398241, 33729, 10275, '<td valign="top">I would have like to see more space around the windows. The windows themselves are very beautiful.</td>', 'I would have like to see more space around the windows. The windows themselves are very beautiful.', '2003-08-25 00:54:39.000000', NULL, 1),
(398242, 33927, 10275, '<td valign="top">This one is fun and creative. Good sharpness too.</td>', 'This one is fun and creative. Good sharpness too.', '2003-08-25 00:55:11.000000', NULL, 1),
(398247, 33955, 7969, '<td valign="top">What an odd yet enjoyable shot.  Curious how you did it.  Be sure to tell when it is over.  Looks like a layer?</td>', 'What an odd yet enjoyable shot.  Curious how you did it.  Be sure to tell when it is over.  Looks like a layer?', '2003-08-25 01:00:48.000000', NULL, 0),
(398248, 33760, 4493, '<td valign="top">Excellent work! I really like this! Congrats on the ribbon!</td>', 'Excellent work! I really like this! Congrats on the ribbon!', '2003-08-25 01:02:29.000000', NULL, 0),
