(398413, 34000, 6912, '<td valign="top">Congratulations Todd. It''s been a while since I''ve seen an "8" score.<br/><br/><i>Message edited by author 2003-08-25 02:57:48.</i></td>', 'Congratulations Todd. It''s been a while since I''ve seen an "8" score.', '2003-08-25 03:55:32.000000', '2003-08-25 03:57:48.000000', 0),
