INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(761004, 33431, 22734, '<td valign="top">beautiful</td>', 'beautiful', '2004-06-12 23:17:41.000000', NULL, 0),
(764668, 33844, 22734, '<td valign="top">very nice mellow study.</td>', 'very nice mellow study.', '2004-06-15 23:24:02.000000', NULL, 0),
(788276, 33075, 12809, '<td valign="top">Simple.  I like it.  I''m wondering if I would like it even better if the bg was white...?  I never see things like this.  Good eye...or idea. :-)</td>', 'Simple.  I like it.  I''m wondering if I would like it even better if the bg was white...?  I never see things like this.  Good eye...or idea. :-)', '2004-06-30 22:16:04.000000', NULL, 0),
(788291, 33075, 10268, '<td valign="top">Immediately when I saw this, I thought how much better it would be with a white background.  My ps skills are not very good, but I decided to take a shot at it, to see if it would look better.<br/> <br/>So I did, but I know some people don''t like having their photos toyed with, but if you''re interested in seeing it, I did it, and I think it makes the photo, which is already great, even better.<br/> <br/>And I can''t help but think, that if it had been white, you could have got a top ten placement.</td>', 'Immediately when I saw this, I thought how much better it would be with a white background.  My ps skills are not very good, but I decided to take a shot at it, to see if it would look better. So I did, but I know some people don''t like having their photos toyed with, but if you''re interested in seeing it, I did it, and I think it makes the photo, which is already great, even better. And I can''t help but think, that if it had been white, you could have got a top ten placement.', '2004-06-30 22:24:08.000000', NULL, 0),
(788295, 33075, 18349, '<td valign="top">I like this, but I can''t help but wonder if the bg was supposed to be white...I can''t get white foam core to look white in my camera, so maybe that''s it?  I don''t know.  Good use of negative space.  :o)</td>', 'I like this, but I can''t help but wonder if the bg was supposed to be white...I can''t get white foam core to look white in my camera, so maybe that''s it?  I don''t know.  Good use of negative space.  :o)', '2004-06-30 22:26:17.000000', NULL, 0),
(788337, 33075, 4793, '<td valign="top">Simple well done photo.</td>', 'Simple well done photo.', '2004-06-30 23:06:44.000000', NULL, 0),
(788369, 33075, 14986, '<td valign="top">Really cool idea for this challenge.  I agree with some of the others that a whiter background would probably enhance the idea a bit, but I do like what you have here.<br/> <br/>The shadow works to add interest without "overshadowing" the pin.  I''m just not a big fan of the minimalistic sort of photos, but I think this one is well done.</td>', 'Really cool idea for this challenge.  I agree with some of the others that a whiter background would probably enhance the idea a bit, but I do like what you have here. The shadow works to add interest without "overshadowing" the pin.  I''m just not a big fan of the minimalistic sort of photos, but I think this one is well done.', '2004-06-30 23:20:51.000000', NULL, 0),
(792764, 33075, 19831, '<td valign="top">Simple and to the point! hehehe<br/>The shadow definetely adds a lot of interest to the shot. Borders always rouse great debates on the site, but I think your border really makes this shot work. The shot is good, but I wonder if it could be better if pin was on left?</td>', 'Simple and to the point! heheheThe shadow definetely adds a lot of interest to the shot. Borders always rouse great debates on the site, but I think your border really makes this shot work. The shot is good, but I wonder if it could be better if pin was on left?', '2004-07-02 18:59:02.000000', NULL, 0),
(832028, 33844, 22734, '<td valign="top">Gorgeous study with ideal use of model.</td>', 'Gorgeous study with ideal use of model.', '2004-07-29 14:38:59.000000', NULL, 0),
(1152769, 33747, 14986, '<td valign="top">Really nice colors and composition on this shot.   I feel like I''m standing right there under it!</td>', 'Really nice colors and composition on this shot.   I feel like I''m standing right there under it!', '2005-02-06 01:16:46.000000', NULL, 0),
(1301741, 34028, 3087, '<td valign="top">Great idea and you know I love the feet dancing image! I think this could be improved by a touch more light on the bells and perhaps by having the bells just a touch nearer to the right hand corner rather than centred horizontally. Love the texture in the cloth.</td>', 'Great idea and you know I love the feet dancing image! I think this could be improved by a touch more light on the bells and perhaps by having the bells just a touch nearer to the right hand corner rather than centred horizontally. Love the texture in the cloth.', '2005-04-18 21:12:59.000000', NULL, 0),
(1318622, 33844, 36538, '<td valign="top">Anastasia:<br/>WOW .. great photo ... LOVE the lighting .. Nicole  has beautiful hair .. please do more photos of her ... <br/>keep up the super work</td>', 'Anastasia:WOW .. great photo ... LOVE the lighting .. Nicole  has beautiful hair .. please do more photos of her ... keep up the super work', '2005-04-24 13:55:13.000000', NULL, 0),
